<script setup lang="ts">
import { invalidateFrom } from '#/api/creative-video/approvals';
import ResourceRecovery from './ResourceRecovery.vue';
import { resourceApi } from '#/api/creative-video/resources';
import { studioStorage } from '#/api/creative-video/storage';
import { computed, ref } from 'vue';
import { ElInput, ElInputNumber, ElButton, ElMessage, ElTable, ElTableColumn, ElTag } from 'element-plus';
import { assetApi } from '#/api/creative-video/assets';
import { intakeApi, validateEvidence } from '#/api/creative-video/intake';
import { allowed } from '#/api/creative-video/permissions';
const props=defineProps<{projectId:number;url:string;mode:'ingest'|'report'}>();
const state=ref(intakeApi.load(props.projectId));const assets=ref(assetApi.list());
function evidenceChanged(){invalidateFrom(props.projectId,1);state.value.revision++;state.value.confirmedRevision=undefined;studioStorage.setItem(`vidcraft-intake-dirty-${props.projectId}`,'true');save();}
function addEvidence(){state.value.evidence.push({id:Math.max(0,...state.value.evidence.map(e=>e.id))+1,statement:'待补充事实或主张',source:'用户提供的说明',level:'待核实',kind:'USER_STATEMENT',excerpt:'',missing:true});evidenceChanged();}
const coverage=computed(()=>[{name:'产品网址',present:!!props.url},{name:'产品说明文档',present:linked.value.some(a=>/\.(pdf|docx?)$/i.test(a.name))},{name:'产品截图',present:linked.value.some(a=>/\.(png|jpe?g|webp)$/i.test(a.name))},{name:'演示录屏',present:linked.value.some(a=>/\.(mp4|mov)$/i.test(a.name))}]);
const linked=computed(()=>assets.value.filter(a=>a.projectId===props.projectId));
function save(){intakeApi.save(props.projectId,state.value);}
function upload(event:Event){try{assetApi.add(Array.from((event.target as HTMLInputElement).files||[]),props.projectId);assets.value=assetApi.list();state.value.revision++;save();}catch(e){ElMessage.warning((e as Error).message);}}
const syncStatus=ref('本地资料');const syncing=ref(false);
async function sync(confirm=false){if(syncing.value)return false;syncing.value=true;studioStorage.setItem(`vidcraft-intake-dirty-${props.projectId}`,'true');const payload={...state.value,assets:linked.value};const fingerprint=JSON.stringify(payload);try{const record=await resourceApi.save(props.projectId,'intake',JSON.parse(fingerprint) as object,confirm);if(JSON.stringify({...state.value,assets:linked.value})!==fingerprint){syncStatus.value='资料在保存期间变化，请重新提交';return false;}syncStatus.value=`服务端资料 R${record.revision} ${record.confirmed?'已确认':'已保存'}`;studioStorage.removeItem(`vidcraft-intake-dirty-${props.projectId}`);return true;}catch{syncStatus.value='资料同步失败或存在版本冲突，本地内容保留';ElMessage.warning(syncStatus.value);return false;}finally{syncing.value=false;}}
async function collect(){try{save();state.value=intakeApi.collect(props.projectId,props.url,linked.value);if(await sync())ElMessage.success('模拟采集已保存服务端，请核对证据');}catch(e){ElMessage.warning((e as Error).message);}}
async function confirm(){try{state.value.evidence.forEach(validateEvidence);}catch(e){ElMessage.warning((e as Error).message);return;}if(await sync(true)){state.value.confirmedRevision=state.value.revision;save();ElMessage.success('当前资料证据已在服务端确认');}}
</script>
<template><div class="intake"><ResourceRecovery :project-id="projectId" kind="intake"/><p role="status">{{ syncStatus }}</p><details><summary>资料覆盖度（仅检查输入渠道，不代表产品已被理解）</summary><p v-for="c in coverage" :key="c.name">{{ c.name }}：{{ c.present?'已提供输入':'缺失，可补充后再分析' }}</p></details><ElTag>资料修订 R{{ state.revision }}</ElTag><ElTag v-if="state.confirmedRevision!==state.revision" type="warning">证据待核对 / 下游需复核</ElTag><template v-if="mode==='ingest'"><p>文件仅记录元数据，不上传内容，不解析敏感资料。</p><input type="file" multiple accept=".pdf,.doc,.docx,.png,.jpg,.jpeg,.webp,.mp4,.mov" :disabled="!allowed('edit')" @change="upload"/><p v-for="a in linked" :key="a.id">{{ a.name }} · {{ a.size }} 字节</p><label><input v-model="state.needsLogin" type="checkbox" @change="save"/> 模拟产品需要登录</label><label v-if="state.needsLogin"><input v-model="state.authorized" type="checkbox" @change="save"/> 我有权使用此演示环境（不收集账号密码）</label><label><input v-model="state.redacted" type="checkbox" @change="save"/> 确认素材已脱敏，未包含真实客户或账户数据</label><ElButton :loading="syncing" :disabled="syncing" @click="collect">开始模拟采集</ElButton></template><template v-else><p>这里仅展示已记录输入与 Mock 推测，不能视为真实网页分析结果。</p><ElTable :data="state.evidence"><ElTableColumn prop="statement" label="内容"/><ElTableColumn prop="level" label="证据等级"/><ElTableColumn prop="source" label="来源"/></ElTable><details v-for="e in state.evidence" :key="e.id"><summary>证据 #{{ e.id }} · {{ e.source }} · {{ e.missing?'缺少细节':'查看来源细节' }}</summary><fieldset :disabled="!allowed('edit')"><label>事实或待核实主张<ElInput v-model="e.statement" type="textarea" @change="evidenceChanged"/></label><label>来源网址／文件名／人工陈述<ElInput v-model="e.source" @change="evidenceChanged"/></label><label>证据等级<select v-model="e.level" @change="evidenceChanged"><option>事实</option><option>推测</option><option>待核实</option></select></label><label>来源类型<select v-model="e.kind" @change="evidenceChanged"><option value="WEB">网页</option><option value="DOCUMENT">文档</option><option value="RECORDING">录屏</option><option value="USER_STATEMENT">人工陈述</option></select></label><label v-if="e.kind==='DOCUMENT'">文档页码<ElInputNumber v-model="e.page" :min="1" @change="evidenceChanged"/></label><label v-if="e.kind==='RECORDING'">录屏时间戳<ElInput v-model="e.timestamp" placeholder="00:15 或 00:01:15" @change="evidenceChanged"/></label><label>来源摘录（用户填写，非自动解析）<ElInput v-model="e.excerpt" type="textarea" :maxlength="5000" @change="evidenceChanged"/></label><label><input v-model="e.missing" type="checkbox" @change="evidenceChanged"/>资料细节不足，需补充核实</label></fieldset><p>“事实”可能仅表示已提交某项输入；录入摘录不等于完成外部真实性验证。</p></details><ElButton v-if="allowed('edit')" @click="addEvidence">补充人工证据</ElButton><ElButton :loading="syncing" :disabled="syncing||!state.evidence.length||!allowed('review')" @click="confirm">确认当前证据</ElButton></template></div></template>
<style scoped>.intake{background:#f2f4fa;padding:20px;border-radius:12px;margin:20px 0}label{display:block;margin:16px 0}p{color:#808ba0;margin:12px 0;font-size:13px}.el-tag{margin-right:8px}</style>
